panels.css:
main{padding:0;height:1080px;display:block}
.wrap{position:relative;height:1080px;padding:56px 60px 0;background:radial-gradient(circle at 10% 20%,rgba(214,62,118,.12),transparent 45%),radial-gradient(circle at 92% 80%,rgba(245,197,24,.16),transparent 48%),var(--cream)}
.k{font-size:30px;font-weight:700;color:var(--ink-2);text-align:center}
.t{font-size:62px;font-weight:900;line-height:1.24;text-align:center;margin-top:10px}
.t em{font-style:normal;color:#D63E76}
.note{position:absolute;left:60px;right:60px;bottom:40px;font-size:22px}
.list{display:flex;flex-direction:column;gap:18px;margin-top:36px}
.r{display:flex;gap:22px;align-items:center;background:#fff;border-radius:24px;padding:22px 26px;box-shadow:0 14px 30px -24px rgba(30,18,25,.45);border-left:14px solid #9a8a92}
.r.a{border-left-color:#D63E76}
.no{flex:0 0 64px;height:64px;border-radius:50%;background:#46293A;color:#fff;font-size:34px;font-weight:900;display:flex;align-items:center;justify-content:center}.r.a .no{background:#D63E76}
.tx{flex:1}.tx b{display:block;font-size:31px;font-weight:900}
.lgs{display:flex;gap:12px;align-items:center;margin:10px 0 6px}.lgs img{height:40px;max-width:150px;object-fit:contain}.lgs i{font-style:normal;font-size:26px;font-weight:900}
.tx span{display:block;font-size:21px;color:var(--ink-2);line-height:1.5}
.yen{font-size:50px;font-weight:900;color:#D63E76;white-space:nowrap}.yen small{font-size:26px}
